import sys

def solve():
    MOD = 998244353
    data = sys.stdin.read().split()
    N = int(data[0])
    S = data[1]
    L = 2 * N

    # Precompute diff[i] = (#B - #W) in the first i characters
    diff = [0] * (L + 1)
    for i in range(1, L + 1):
        if S[i-1] == 'B':
            diff[i] = diff[i-1] + 1
        else:
            diff[i] = diff[i-1] - 1

    # dp[b] = number of ways to have B-stack size b after processing some prefix
    dp = [0] * (L + 1)
    dp[0] = 1  # f[0][0] = 1

    for i in range(L):
        ndp = [0] * (L + 1)
        # Valid range of b: max(0, diff[i]) <= b <= (i + diff[i]) // 2
        low = max(0, diff[i])
        high = (i + diff[i]) // 2
        if high < low:
            dp = ndp
            continue

        for b in range(low, high + 1):
            if dp[b] == 0:
                continue
            w = b - diff[i]
            if w < 0:
                continue

            if S[i] == 'B':
                # Option A: push onto B-stack (match to future white)
                b_new = b + 1
                if i + 1 < L:
                    if b_new >= 1:
                        ndp[b_new] = (ndp[b_new] + dp[b]) % MOD
                else:
                    if b_new == 0:
                        ndp[b_new] = (ndp[b_new] + dp[b]) % MOD

                # Option B: pop from W-stack (match to past white), requires w >= 1
                if w >= 1:
                    b_new = b
                    if i + 1 < L:
                        if b_new >= 1:
                            ndp[b_new] = (ndp[b_new] + dp[b]) % MOD
                    else:
                        if b_new == 0:
                            ndp[b_new] = (ndp[b_new] + dp[b]) % MOD

            else:  # S[i] == 'W'
                # Option A: pop from B-stack (match to past black), requires b >= 1
                if b >= 1:
                    b_new = b - 1
                    if i + 1 < L:
                        if b_new >= 1:
                            ndp[b_new] = (ndp[b_new] + dp[b]) % MOD
                    else:
                        if b_new == 0:
                            ndp[b_new] = (ndp[b_new] + dp[b]) % MOD

                # Option B: push onto W-stack (match to future black)
                b_new = b
                if i + 1 < L:
                    if b_new >= 1:
                        ndp[b_new] = (ndp[b_new] + dp[b]) % MOD
                else:
                    if b_new == 0:
                        ndp[b_new] = (ndp[b_new] + dp[b]) % MOD

        dp = ndp

    print(dp[0] % MOD)

