class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)                     # maximal possible |alternating sum|
        if abs(k) > total:                    # impossible to reach k
            return -1

        offset = total                         # shift to make sums non‑negative
        size = 2 * total + 1                   # number of possible sum values
        # dp[sum_index][par] = max product (or -1)
        dp = [[-1, -1] for _ in range(size)]

        for x in nums:
            # copy current table – case where we skip x
            ndp = [row[:] for row in dp]

            # start a new subsequence consisting only of x (length 1 → odd parity)
            if x <= limit:
                idx = x + offset
                if ndp[idx][1] < x:
                    ndp[idx][1] = x

            # extend every already reachable subsequence by appending x
            for i in range(size):
                s = i - offset                  # current alternating sum
                cur0, cur1 = dp[i][0], dp[i][1]

                # extend subsequence with even length (parity 0) → sign '+'
                if cur0 != -1:
                    ns = s + x
                    if -offset <= ns <= offset:
                        prod = cur0 * x
                        if prod <= limit:
                            j = ns + offset
                            if ndp[j][1] < prod:
                                ndp[j][1] = prod

                # extend subsequence with odd length (parity 1) → sign '-'
                if cur1 != -1:
                    ns = s - x
                    if -offset <= ns <= offset:
                        prod = cur1 * x
                        if prod <= limit:
                            j = ns + offset
                            if ndp[j][0] < prod:
                                ndp[j][0] = prod
            dp = ndp

        # retrieve answer for required sum k
        idx = k + offset
        if not (0 <= idx < size):
            return -1
        ans = max(dp[idx][0], dp[idx][1])
        return ans if ans >= 0 else -1

