import math

def precompute(N):
    # distinct[i] = number of distinct prime factors of i
    distinct = [0] * (N + 1)
    is_comp = bytearray(N + 1)
    primes = []
    for i in range(2, N + 1):
        if not is_comp[i]:
            primes.append(i)
            distinct[i] = 1
        for p in primes:
            ip = i * p
            if ip > N:
                break
            is_comp[ip] = 1
            if i % p == 0:
                distinct[ip] = distinct[i]
                break
            else:
                distinct[ip] = distinct[i] + 1
    # best[i] = largest j <= i with distinct[j] == 2
    best = [0] * (N + 1)
    for i in range(1, N + 1):
        if distinct[i] == 2:
            best[i] = i
        else:
            best[i] = best[i - 1]
    return best

