class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # Pre‑compute powers of 4 up to a value larger than 10^9
        pow4 = [1]                     # 4^0
        while pow4[-1] <= 10**9:
            pow4.append(pow4[-1] * 4)  # 4^1, 4^2, ...

        # Helper: prefix sum of steps for numbers 1..N
        def prefix(N: int) -> int:
            if N <= 0:
                return 0
            total = 0
            # step k corresponds to interval [4^{k-1}, 4^k - 1]
            for k in range(1, len(pow4)):
                lower = pow4[k - 1]          # 4^{k-1}
                upper = pow4[k] - 1          # 4^k - 1
                if lower > N:
                    break
                cur_upper = min(upper, N)
                cnt = cur_upper - lower + 1
                total += cnt * k
            return total

        ans = 0
        for l, r in queries:
            total_steps = prefix(r) - prefix(l - 1)
            # each operation reduces the total step count by 2
            ans += (total_steps + 1) // 2
        return ans

