from collections import deque

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    adj = [[] for _ in range(N)]
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * N
    comps = []  # list of (size, a, b)
    for v in range(N):
        if color[v] == -1:
            q = deque([v])
            color[v] = 0
            a = 1
            b = 0
            size = 1
            while q:
                u = q.popleft()
                for w in adj[u]:
                    if color[w] == -1:
                        color[w] = 1 - color[u]
                        if color[w] == 0:
                            a += 1
                        else:
                            b += 1
                        size += 1
                        q.append(w)
            comps.append((size, a, b))
    O = 0
    P = 0
    for size, a, b in comps:
        if size % 2 == 1:
            O += 1
        else:
            P = (P + a) % 2
    if N % 2 == 1:
        if M % 2 == 1:
            print("Aoki")
        else:
            print("Takahashi")
    else:
        if O > 0:
            print("Aoki")
        else:
            if (P + M) % 2 == 1:
                print("Aoki")
            else:
                print("Takahashi")

