class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # Precompute prime factorizations for digits 1..9
        digit_exp = [None] * 10
        for d in range(1, 10):
            e2 = e3 = e5 = e7 = 0
            x = d
            while x % 2 == 0:
                e2 += 1
                x //= 2
            while x % 3 == 0:
                e3 += 1
                x //= 3
            while x % 5 == 0:
                e5 += 1
                x //= 5
            while x % 7 == 0:
                e7 += 1
                x //= 7
            digit_exp[d] = (e2, e3, e5, e7)

        # Precompute required prime exponents for each possible sum (0..81)
        need2 = [0] * 82
        need3 = [0] * 82
        need5 = [0] * 82
        need7 = [0] * 82
        can = [True] * 82  # whether the sum can be a divisor of a product of digits
        for s in range(1, 82):
            e2 = e3 = e5 = e7 = 0
            x = s
            while x % 2 == 0:
                e2 += 1
                x //= 2
            while x % 3 == 0:
                e3 += 1
                x //= 3
            while x % 5 == 0:
                e5 += 1
                x //= 5
            while x % 7 == 0:
                e7 += 1
                x //= 7
            need2[s] = e2
            need3[s] = e3
            need5[s] = e5
            need7[s] = e7
            if x != 1:  # remaining prime factor > 7
                can[s] = False

        from functools import lru_cache

        # Count numbers <= bound that contain no digit zero and are beautiful
        def count_beautiful(bound: int) -> int:
            if bound <= 0:
                return 0
            digits = list(map(int, str(bound)))
            n = len(digits)

            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, started: bool,
                    sum_val: int, e2: int, e3: int, e5: int, e7: int) -> int:
                if pos == n:
                    if not started:
                        return 0
                    # Check condition: product must be divisible by sum
                    if (can[sum_val] and
                        e2 >= need2[sum_val] and
                        e3 >= need3[sum_val] and
                        e5 >= need5[sum_val] and
                        e7 >= need7[sum_val]):
                        return 1
                    return 0
                limit = digits[pos] if tight else 9
                total = 0
                for d in range(limit + 1):
                    ntight = tight and (d == limit)
                    if not started:
                        if d == 0:
                            # still no non‑zero digit placed
                            total += dfs(pos + 1, ntight, False, 0, 0, 0, 0, 0)
                        else:
                            ne2, ne3, ne5, ne7 = digit_exp[d]
                            total += dfs(pos + 1, ntight, True, d, ne2, ne3, ne5, ne7)
                    else:
                        if d == 0:
                            continue  # zero not allowed after start
                        new_sum = sum_val + d
                        if new_sum > 81:
                            continue
                        ne2, ne3, ne5, ne7 = digit_exp[d]
                        # cap exponents to maximum needed for any sum
                        e2n = e2 + ne2
                        if e2n > 6:
                            e2n = 6
                        e3n = e3 + ne3
                        if e3n > 4:
                            e3n = 4
                        e5n = e5 + ne5
                        if e5n > 2:
                            e5n = 2
                        e7n = e7 + ne7
                        if e7n > 2:
                            e7n = 2
                        total += dfs(pos + 1, ntight, True, new_sum, e2n, e3n, e5n, e7n)
                return total

            return dfs(0, True, False, 0, 0, 0, 0, 0)

        # Count numbers <= bound that contain no digit zero (any beauty)
        def count_total(bound: int) -> int:
            if bound <= 0:
                return 0
            digits = list(map(int, str(bound)))
            n = len(digits)

            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, started: bool) -> int:
                if pos == n:
                    return 1 if started else 0
                limit = digits[pos] if tight else 9
                total = 0
                for d in range(limit + 1):
                    ntight = tight and (d == limit)
                    if not started:
                        if d == 0:
                            total += dfs(pos + 1, ntight, False)
                        else:
                            total += dfs(pos + 1, ntight, True)
                    else:
                        if d == 0:
                            continue
                        total += dfs(pos + 1, ntight, True)
                return total

            return dfs(0, True, False)

        # Number of integers in [l, r] that are beautiful
        total_range = r - l + 1
        # f(x) = count of numbers <= x without zero digit that are NOT beautiful
        f_r = count_total(r) - count_beautiful(r)
        f_l1 = count_total(l - 1) - count_beautiful(l - 1)
        not_beautiful = f_r - f_l1
        return total_range - not_beautiful

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        N = n + m - 1
        word = [None] * N

        # Process T constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if word[pos] is None:
                        word[pos] = str2[j]
                    elif word[pos] != str2[j]:
                        return ""

        # Initialize data for F constraints
        unfixed = [0] * n
        match = [0] * n
        covering = [[] for _ in range(N)]

        for i in range(n):
            if str1[i] == 'F':
                for j in range(m):
                    pos = i + j
                    if word[pos] is None:
                        unfixed[i] += 1
                    else:
                        if word[pos] == str2[j]:
                            match[i] += 1
                    covering[pos].append(i)
                if unfixed[i] == 0 and match[i] == m:
                    return ""

        # Greedy assignment for remaining positions
        for p in range(N):
            if word[p] is not None:
                continue
            assigned = False
            for c in 'abcdefghijklmnopqrstuvwxyz':
                valid = True
                for i in covering[p]:
                    offset = p - i
                    new_unfixed = unfixed[i] - 1
                    new_match = match[i] + (1 if c == str2[offset] else 0)
                    if new_unfixed == 0 and new_match == m:
                        valid = False
                        break
                if valid:
                    word[p] = c
                    for i in covering[p]:
                        offset = p - i
                        unfixed[i] -= 1
                        if c == str2[offset]:
                            match[i] += 1
                    assigned = True
                    break
            if not assigned:
                return ""

        return ''.join(word)

