class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # Directions in clockwise order: down-right, down-left, up-left, up-right
        dx = [1, 1, -1, -1]
        dy = [1, -1, -1, 1]
        # Next value in the alternating sequence: 0->2, 1->2, 2->0
        nxt = [2, 2, 0]

        # dp[i][j][d] = longest alternating sequence starting at (i,j) and moving in direction d
        dp = [[[0]*4 for _ in range(m)] for _ in range(n)]
        # pref[i][j][d] = longest alternating sequence ending at (i,j) that started with 1 and arrived from direction d
        pref = [[[0]*4 for _ in range(m)] for _ in range(n)]

        # Compute dp by scanning in reverse order of direction d
        for d in range(4):
            if d == 0:
                i_range = range(n-1, -1, -1)
                j_range = range(m-1, -1, -1)
            elif d == 1:
                i_range = range(n-1, -1, -1)
                j_range = range(m)
            elif d == 2:
                i_range = range(n)
                j_range = range(m)
            else:  # d == 3
                i_range = range(n)
                j_range = range(m-1, -1, -1)
            for i in i_range:
                for j in j_range:
                    val = grid[i][j]
                    ni, nj = i+dx[d], j+dy[d]
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == nxt[val]:
                        dp[i][j][d] = 1 + dp[ni][nj][d]
                    else:
                        dp[i][j][d] = 1

        # Compute pref by scanning in forward order of direction d
        for d in range(4):
            if d == 0:
                i_range = range(n)
                j_range = range(m)
            elif d == 1:
                i_range = range(n)
                j_range = range(m-1, -1, -1)
            elif d == 2:
                i_range = range(n-1, -1, -1)
                j_range = range(m-1, -1, -1)
            else:  # d == 3
                i_range = range(n-1, -1, -1)
                j_range = range(m)
            for i in i_range:
                for j in j_range:
                    val = grid[i][j]
                    if val == 1:
                        pref[i][j][d] = 1
                    else:
                        pi, pj = i-dx[d], j-dy[d]
                        if 0 <= pi < n and 0 <= pj < m:
                            prev_val = grid[pi][pj]
                            if pref[pi][pj][d] > 0 and val == nxt[prev_val]:
                                pref[i][j][d] = pref[pi][pj][d] + 1
                            else:
                                pref[i][j][d] = 0
                        else:
                            pref[i][j][d] = 0

        # Find the maximum length
        ans = 0
        for i in range(n):
            for j in range(m):
                for d in range(4):
                    # No turn: straight segment ending at (i,j) in direction d
                    if pref[i][j][d] > 0:
                        if pref[i][j][d] > ans:
                            ans = pref[i][j][d]
                    # One turn: turn at (i,j) from direction d to clockwise direction d_rot
                    d_rot = (d + 1) % 4
                    if pref[i][j][d] > 0 and dp[i][j][d_rot] >= 2:
                        total = pref[i][j][d] + dp[i][j][d_rot] - 1
                        if total > ans:
                            ans = total
        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        """
        Returns the length of the shortest substring of `s` that matches the pattern `p`.
        The pattern contains exactly two '*' characters.  It can be written as
        A * B * C  where A, B, C are (possibly empty) fixed strings.
        A matching substring must start with A (or be empty if A is empty),
        contain B somewhere after the end of A, and end with C (or be empty if C is empty).
        The two '*' match any (possibly empty) sequence of characters.
        If no such substring exists, return -1.  The empty substring is valid only
        when A, B, and C are all empty.
        """
        n = len(s)
        # locate the two stars
        star1 = p.find('*')
        star2 = p.find('*', star1 + 1)
        A = p[:star1]
        B = p[star1 + 1:star2]
        C = p[star2 + 1:]
        lenA, lenB, lenC = len(A), len(B), len(C)

        # all three parts empty -> empty substring matches
        if lenA == 0 and lenB == 0 and lenC == 0:
            return 0

        # helper: KMP to find all (possibly overlapping) occurrences of a non‑empty pattern
        def get_occurrences(text: str, pat: str):
            m = len(pat)
            if m == 0:
                return []          # should not be called with empty pattern
            # build prefix function
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j
            # scan text
            res = []
            j = 0
            for i in range(len(text)):
                while j > 0 and pat[j] != text[i]:
                    j = pi[j - 1]
                if pat[j] == text[i]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]
            return res

        # compute occurrence lists for the non‑empty parts
        occA = get_occurrences(s, A) if lenA > 0 else None
        occB = get_occurrences(s, B) if lenB > 0 else None
        occC = get_occurrences(s, C) if lenC > 0 else None

        # ----- handle the different emptiness combinations -----
        INF = 10 ** 9

        # A empty, B empty, C non‑empty  -> pattern "* * C"
        if lenA == 0 and lenB == 0 and lenC > 0:
            if not occC:
                return -1
            # shortest is just C itself
            return lenC

        # A empty, B non‑empty, C empty  -> pattern "*B*"
        if lenA == 0 and lenB > 0 and lenC == 0:
            if not occB:
                return -1
            return lenB

        # A non‑empty, B empty, C empty  -> pattern "A*"
        if lenA > 0 and lenB == 0 and lenC == 0:
            if not occA:
                return -1
            return lenA

        # A empty, B non‑empty, C non‑empty  -> pattern "*B*C"
        if lenA == 0 and lenB > 0 and lenC > 0:
            if not occB or not occC:
                return -1
            # need minimal (k - j) + lenC with k >= j + lenB
            c_idx = 0
            best = INF
            for j in occB:
                while c_idx < len(occC) and occC[c_idx] < j + lenB:
                    c_idx += 1
                if c_idx < len(occC):
                    k = occC[c_idx]
                    length = (k - j) + lenC
                    if length < best:
                        best = length
            return best if best != INF else -1

        # A non‑empty, B empty, C non‑empty  -> pattern "A*C"
        if lenA > 0 and lenB == 0 and lenC > 0:
            if not occA or not occC:
                return -1
            # need minimal (k - i) + lenC with k >= i + lenA
            c_idx = 0
            best = INF
            for i in occA:
                while c_idx < len(occC) and occC[c_idx] < i + lenA:
                    c_idx += 1
                if c_idx < len(occC):
                    k = occC[c_idx]
                    length = (k - i) + lenC
                    if length < best:
                        best = length
            return best if best != INF else -1

        # A non‑empty, B non‑empty, C empty  -> pattern "A*B*"
        if lenA > 0 and lenB > 0 and lenC == 0:
            if not occA or not occB:
                return -1
            # need minimal (j + lenB - i) with i + lenA <= j
            b_idx = 0
            best = INF
            for i in occA:
                while b_idx < len(occB) and occB[b_idx] < i + lenA:
                    b_idx += 1
                if b_idx < len(occB):
                    j = occB[b_idx]
                    length = (j + lenB) - i
                    if length < best:
                        best = length
            return best if best != INF else -1

        # All three non‑empty  -> pattern "A*B*C"
        if lenA > 0 and lenB > 0 and lenC > 0:
            if not occA or not occB or not occC:
                return -1
            a_idx = 0      # points to the largest i with i + lenA <= current j
            c_idx = 0      # points to the first k >= j + lenB
            best = INF
            for j in occB:
                # advance a_idx to the last i satisfying i + lenA <= j
                while a_idx + 1 < len(occA) and occA[a_idx + 1] + lenA <= j:
                    a_idx += 1
                if occA[a_idx] + lenA > j:
                    continue          # no A before this j
                i = occA[a_idx]
                # advance c_idx to the first k >= j + lenB
                while c_idx < len(occC) and occC[c_idx] < j + lenB:
                    c_idx += 1
                if c_idx >= len(occC):
                    break              # no C left for any later j
                k = occC[c_idx]
                length = (k - i) + lenC
                if length < best:
                    best = length
            return best if best != INF else -1

        # Should never reach here because all cases are covered
        return -1

