def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out = []
    for _ in range(T):
        N = int(next(it))
        A, M = solve_one(N)
        out.append(f"{A} {M}")
    sys.stdout.write("\n".join(out))


