        def __init__(self, n):
            self.n = n
            size = 4 * n + 5
            self.mx = [0] * size
            self.lazy = [0] * size
            self._build(1, 1, n)

        def _build(self, node, l, r):
            if l == r:
                self.mx[node] = l
            else:
                m = (l + r) // 2
                self._build(node * 2, l, m)
                self._build(node * 2 + 1, m + 1, r)
                self.mx[node] = r

        def _push(self, node):
            v = self.lazy[node]
            if v:
                left = node * 2
                right = node * 2 + 1
                self.mx[left] += v
                self.mx[right] += v
                self.lazy[left] += v
                self.lazy[right] += v
                self.lazy[node] = 0

        def _range_add(self, node, l, r, ql, qr, val):
            if ql > r or qr < l:
                return
            if ql <= l and r <= qr:
                self.mx[node] += val
                self.lazy[node] += val
                return
            self._push(node)
            m = (l + r) // 2
            self._range_add(node * 2, l, m, ql, qr, val)
            self._range_add(node * 2 + 1, m + 1, r, ql, qr, val)
            left = node * 2
            right = node * 2 + 1
            self.mx[node] = self.mx[left] if self.mx[left] > self.mx[right] else self.mx[right]

        def range_add(self, ql, qr, val):
            self._range_add(1, 1, self.n, ql, qr, val)

        def _first_ge(self, node, l, r, val):
            if self.mx[node] < val:
                return self.n + 1
            if l == r:
                return l
            self._push(node)
            m = (l + r) // 2
            left = node * 2
            right = node * 2 + 1
            if self.mx[left] >= val:
                return self._first_ge(left, l, m, val)
            else:
                return self._first_ge(right, m + 1, r, val)

        def first_ge(self, val):
            return self._first_ge(1, 1, self.n, val)

        def _collect(self, node, l, r, ans):
            if l == r:
                ans[l] = self.mx[node]
                return
            self._push(node)
            m = (l + r) // 2
            self._collect(node * 2, l, m, ans)
            self._collect(node * 2 + 1, m + 1, r, ans)

        def collect(self, ans):
            self._collect(1, 1, self.n, ans)

    seg = SegTree(MAX)

    for L, R in intervals:
