def mat_mult(A, B, mod):
    n = len(A)
    C = [[0]*n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            aik = A[i][k]
            if aik == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + aik * B[k][j]) % mod
    return C

def mat_pow(A, power, mod):
    n = len(A)
    R = [[0]*n for _ in range(n)]
    for i in range(n):
