        R = int(next(it))
        intervals.append((L, R))

    # Precompute constants
    S = 1 << B
    mask = S - 1
    M_mask = ((1 << (B - A + 1)) - 1) << (A - 1)

    # Transition for a single good square (value 1)
    trans1 = array('I', [0]) * S
    for s in range(S):
        new_bit = 1 if (s & M_mask) else 0
        trans1[s] = ((s << 1) | new_bit) & mask

    # Determine the maximum length of a good segment to know how many powers of two to precompute
    cur = 2
    max_good = 0
    for L, R in intervals:
        if cur < L:
            good_len = L - cur
            if good_len > max_good:
                max_good = good_len
        cur = R + 1
    if cur <= N:
        good_len = N - cur + 1
        if good_len > max_good:
            max_good = good_len
    # Ensure at least one level (max_good can be 0 only if N=1, impossible)
    if max_good == 0:
        max_good = 1

    maxK = max_good.bit_length()  # number of bits needed to represent any good length

    # Precompute T[k] = f_1^{2^k} for k = 0 .. maxK-1
    T = [trans1]
    for k in range(1, maxK):
        prev = T[-1]
        cur_arr = array('I', [0]) * S
        p = prev
        for s in range(S):
            cur_arr[s] = p[p[s]]
        T.append(cur_arr)

    def apply_good(state, length):
        k = 0
        T_local = T
        while length:
            if length & 1:
                state = T_local[k][state]
            length >>= 1
            k += 1
        return state

    def apply_bad(state, length):
        if length >= B:
            return 0
        else:
            return (state << length) & mask

    # Process all positions from 2 to N
    state = 1  # reachable[1] = True
    cur = 2
    for L, R in intervals:
        if cur < L:
            good_len = L - cur
            if good_len > 0:
                state = apply_good(state, good_len)
        bad_len = R - L + 1
        if bad_len > 0:
            state = apply_bad(state, bad_len)
        cur = R + 1
    if cur <= N:
        good_len = N - cur + 1
        if good_len > 0:
            state = apply_good(state, good_len)

    # Check if N is reachable (LSB of the state)
