from typing import List
from collections import defaultdict

class SegmentTree:
    """Segment tree for range maximum subarray sum queries.
    Each node stores a tuple (total, max_prefix, max_suffix, max_subarray).
    """
    __slots__ = ('n', 'tree')

    def __init__(self, arr: List[int]):
        self.n = len(arr)
        self.tree = [None] * (4 * self.n)
        if self.n > 0:
            self._build(1, 0, self.n - 1, arr)

    def _build(self, node: int, l: int, r: int, arr: List[int]):
        if l == r:
            v = arr[l]
            self.tree[node] = (v, v, v, v)
        else:
            mid = (l + r) // 2
            self._build(node * 2, l, mid, arr)
            self._build(node * 2 + 1, mid + 1, r, arr)
            self.tree[node] = self._combine(self.tree[node * 2], self.tree[node * 2 + 1])

    @staticmethod
    def _combine(left, right):
        # left, right are tuples (total, pref, suff, best)
        total = left[0] + right[0]
        pref = max(left[1], left[0] + right[1])
        suff = max(right[2], right[0] + left[2])
        best = max(left[3], right[3], left[2] + right[1])
        return (total, pref, suff, best)

    def query(self, ql: int, qr: int):
        """Return the node information for subarray [ql, qr] (inclusive)."""
        if ql > qr:
            raise ValueError("Invalid range")
        return self._query(1, 0, self.n - 1, ql, qr)

    def _query(self, node: int, l: int, r: int, ql: int, qr: int):
        if ql > r or qr < l:
            return None
        if ql <= l and r <= qr:
            return self.tree[node]
        mid = (l + r) // 2
        left_res = self._query(node * 2, l, mid, ql, qr)
        right_res = self._query(node * 2 + 1, mid + 1, r, ql, qr)
        if left_res is None:
            return right_res
        if right_res is None:
            return left_res
        return self._combine(left_res, right_res)


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Build segment tree for the whole array
        seg = SegmentTree(nums)

        # Original maximum subarray sum (no deletion)
        ans = seg.query(0, n - 1)[3]

        # Map each distinct value to its positions
        pos_dict = defaultdict(list)
        for i, v in enumerate(nums):
            pos_dict[v].append(i)

        # For each distinct value, consider deleting it
        for v, pos in pos_dict.items():
            start = 0
            nodes = []
            # Process intervals that avoid v
            for p in pos:
                if start <= p - 1:
                    nodes.append(seg.query(start, p - 1))
                start = p + 1
            if start <= n - 1:
                nodes.append(seg.query(start, n - 1))

            if not nodes:
                # The value appears everywhere – cannot delete it
                continue

            # Combine intervals sequentially to get max subarray sum after deletion
            cur = nodes[0]
            for i in range(1, len(nodes)):
                cur = SegmentTree._combine(cur, nodes[i])
            ans = max(ans, cur[3])

        return ans

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        # Edge case: k must be in valid range
        if k < 0 or k > n - 1:
            return 0

        # Precompute factorials up to n-1
        fact = [1] * n
        for i in range(1, n):
            fact[i] = fact[i-1] * i % MOD

        inv_fact = [1] * n
        if n >= 1:
            inv_fact[n-1] = pow(fact[n-1], MOD - 2, MOD)
            for i in range(n-2, -1, -1):
                inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a-b] % MOD

        # Number of compositions: C(n-1, k)
        combs = comb(n-1, k)

        # m * (m-1)^(n-k-1)
        exp = n - k - 1
        if exp == 0:
            power = 1
        elif m - 1 == 0:
            power = 0
        else:
            power = pow(m - 1, exp, MOD)

        result = combs * m % MOD * power % MOD
        return result

