        print(max(A))
        return

    # Special case K = N: XOR of all elements
    if K == N:
        total = 0
        for x in A:
            total ^= x
        print(total)
        return

    # Special case K = N-1: XOR of all except one element
    if K == N - 1:
        total = 0
        for x in A:
            total ^= x
        best = 0
        for x in A:
            val = total ^ x
            if val > best:
                best = val
        print(best)
        return

    # General case: enumerate all K‑subsets.
    # The constraint guarantees binom(N, K) ≤ 10^6, so enumeration is feasible.
    best = 0
    for comb in itertools.combinations(A, K):
        x = 0
        for v in comb:
            x ^= v
        if x > best:
            best = x
    print(best)

