from typing import List

class DSU:
    __slots__ = ("parent", "size")

    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x: int) -> int:
        # iterative path compression
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x: int, y: int) -> None:
        xr = self.find(x)
        yr = self.find(y)
        if xr == yr:
            return
        # union by size
        if self.size[xr] < self.size[yr]:
            xr, yr = yr, xr
        self.parent[yr] = xr
        self.size[xr] += self.size[yr]


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        dsu = DSU(n)

        # map each value to its index (values are unique)
        pos = {v: i for i, v in enumerate(nums)}

        # firstDiv[m] = index of any divisor of m that is present in nums
        # -1 means no divisor seen yet
        firstDiv = [-1] * (threshold + 1)

        # single pass: for each value v (≤ threshold) walk through its multiples.
        # If the multiple already has a divisor stored, we union the current
        # index with that divisor; otherwise we store the current index as the
        # representative divisor of the multiple.
        for v, idx in pos.items():
            if v > threshold:
                continue
            # iterate over multiples m = v, 2v, 3v, ... ≤ threshold
            for m in range(v, threshold + 1, v):
                other = firstDiv[m]
                if other == -1:
                    firstDiv[m] = idx
                else:
                    dsu.union(idx, other)

        # count distinct DSU roots – each isolated value > threshold stays alone
        roots = set()
        for i in range(n):
            roots.add(dsu.find(i))

        return len(roots)
